```typescript
import React from 'react';
import DOMPurify from 'dompurify';

export function CommentView({ comment }) {
  // XSS 방지를 위해 DOMPurify로 HTML 입력값을 sanitize하여 안전하게 렌더링
  const sanitizedComment = DOMPurify.sanitize(comment);

  return (
    <div className="comment">
      <h3>User said:</h3>
      <div dangerouslySetInnerHTML={{ __html: sanitizedComment }} />
    </div>
  );
}
```
한줄 요약: DOMPurify를 사용하여 사용자 입력 HTML을 안전하게 sanitize하고 XSS 위험을 제거합니다.
